export const envListShapes = [
    {
        command: "env-list",
        handler: (result) => {
            const r = result;
            const envs = Array.isArray(r.envs) ? r.envs : [];
            return {
                ...r,
                shape: r.shape ?? "env-list",
                schemaVersion: r.schemaVersion ?? 1,
                envs: envs.map((v) => {
                    const { path: _path, ...rest } = v;
                    return rest;
                }),
            };
        },
    },
];
